package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.PreparacionRecuentoCajaDto; import com.citacloud.springboot.contacloud.app.models.*; import net.sf.jasperreports.engine.*; import net.sf.jasperreports.engine.data.JRMapCollectionDataSource; import org.junit.jupiter.api.Test;
import java.io.*; import java.math.BigDecimal; import java.nio.file.*; import java.time.OffsetDateTime; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class RecuentoCajaContratoTest {
 @Test void clasificaCuadreSobranteYFaltante(){assertThat(RecuentoCaja.resultado(BigDecimal.ZERO)).isEqualTo(ResultadoRecuentoCaja.BALANCED);assertThat(RecuentoCaja.resultado(new BigDecimal("0.01"))).isEqualTo(ResultadoRecuentoCaja.OVERAGE);assertThat(RecuentoCaja.resultado(new BigDecimal("-0.01"))).isEqualTo(ResultadoRecuentoCaja.SHORTAGE);}
 @Test void conservaRelacionesDeLaSesionAlCrearElRecuento(){SesionCaja sesion=mock(SesionCaja.class);Caja caja=mock(Caja.class);Sucursal sucursal=mock(Sucursal.class);Moneda moneda=mock(Moneda.class);Usuario usuario=mock(Usuario.class);UUID sesionId=UUID.randomUUID(),cajaId=UUID.randomUUID(),sucursalId=UUID.randomUUID(),monedaId=UUID.randomUUID(),usuarioId=UUID.randomUUID();when(sesion.getId()).thenReturn(sesionId);when(sesion.getCajaId()).thenReturn(cajaId);when(sesion.getSucursalId()).thenReturn(sucursalId);when(sesion.getMonedaId()).thenReturn(monedaId);when(sesion.getCaja()).thenReturn(caja);when(sesion.getSucursal()).thenReturn(sucursal);when(sesion.getMoneda()).thenReturn(moneda);when(sesion.getUsuarioApertura()).thenReturn(usuario);RecuentoCaja recuento=new RecuentoCaja(UUID.randomUUID(),UUID.randomUUID(),"RCJ-000001",sesion,OffsetDateTime.now(),usuarioId,new BigDecimal("100"),new BigDecimal("90"),null,UUID.randomUUID());assertThat(recuento.getCaja()).isSameAs(caja);assertThat(recuento.getSucursal()).isSameAs(sucursal);assertThat(recuento.getMoneda()).isSameAs(moneda);assertThat(recuento.getUsuario()).isSameAs(usuario);assertThat(recuento.getSesion()).isSameAs(sesion);}
 @Test void preparacionCiegaNoExponeEsperadoNiDiferencia(){Set<String> fields=Arrays.stream(PreparacionRecuentoCajaDto.class.getRecordComponents()).map(java.lang.reflect.RecordComponent::getName).collect(java.util.stream.Collectors.toSet());assertThat(fields).doesNotContain("esperado","expectedAmount","diferencia","difference","faltante","sobrante");}
 @Test void plantillaPdfCompilaYGeneraComprobanteCompacto() throws Exception {try(InputStream in=getClass().getResourceAsStream("/reports/cash-count/cash-count.jrxml")){assertThat(in).isNotNull();JasperReport report=JasperCompileManager.compileReport(in);Map<String,Object> p=new HashMap<>();p.put("companyName","Empresa DEMO");p.put("companyTaxId","123-45678-9");p.put("companyAddress","Santo Domingo");p.put("companyPhone","(809) 555-0101");p.put("companyEmail","demo@example.com");p.put("companyLogo",null);p.put("number","RCJ-000001");p.put("cash","Caja 1");p.put("branch","Sucursal Principal");p.put("dateTime","25/10/2026 17:10");p.put("user","admin");p.put("currency","DOP");p.put("expected",new BigDecimal("18450"));p.put("counted",new BigDecimal("18300"));p.put("difference",new BigDecimal("-150"));p.put("result","FALTANTE DE CAJA");p.put("notes","Recuento de cambio de turno");Collection<Map<String,?>> rows=new ArrayList<>();rows.add(Map.of("denomination",new BigDecimal("2000"),"quantity",8,"subtotal",new BigDecimal("16000")));rows.add(Map.of("denomination",new BigDecimal("500"),"quantity",4,"subtotal",new BigDecimal("2000")));rows.add(Map.of("denomination",new BigDecimal("100"),"quantity",3,"subtotal",new BigDecimal("300")));byte[] pdf=JasperExportManager.exportReportToPdf(JasperFillManager.fillReport(report,p,new JRMapCollectionDataSource(rows)));assertThat(pdf.length).isGreaterThan(1000);Path out=Path.of("target","cash-count-preview.pdf");Files.write(out,pdf);}}
}
